import styles from "./pricing.module.css";
import PricingOne from './priceOne.js'
import PricingTwo from './priceTwo.js'

import React, { useState } from 'react';


function Pricing(props) {

  const [priceOne, setPriceOne] = useState(false);

  const handlePriceOne = () => {
    setPriceOne(false)

    
  };

  const handlePriceTwo = () => {
    setPriceOne(true)
  };
  return (
    <div>
      
      <section class="pricing row">
        <div class="col-12">
          <p className={styles.mainText} ref={props.pageScrollPricing}>
            Тарифы
          </p>      
        </div> 
      </section>
      <div className={styles.buttonPriceGroup}>


      <input 
        type="radio"
        className="btn-check"
        name="btnradio"
        id="btnradio1"
        autoComplete="off"
        defaultChecked
        onClick={handlePriceOne}
        
        />

<label class="btn btn-outline-primary" for="btnradio1" >Полная аналитика Wildberries</label>

<div className={styles.blockBtn}/>
<input 
        type="radio"
        className="btn-check"
        name="btnradio"
        id="btnradio2"
        autoComplete="off"
        onClick={handlePriceTwo}
      />

<label  class="btn btn-outline-primary" for="btnradio2">Аналитика рекламы Wildberries</label>

</div>
{priceOne === false ? <PricingOne /> : <PricingTwo />}


    </div>
  );
}

export default Pricing;
